      "level": "N5",
      "pattern": "〜の",
      "meaningZh": "的；名词化；说明语气",
      "formation": "N + の + N；V/い形普通形 + の；な形/N肯定非过去 + なの；な形/N过去・否定普通形 + の",
      "note": "连接名词时相当于“的”；接在普通形后可把内容名词化。な形容词和名词只有肯定非过去形使用「なの」，如「静かなの／学生なの」；过去或否定形直接接「の」，如「静かだったの／学生ではないの」。句末的「の」还可用于口语中的说明或提问，礼貌表达常用「んです／のです」。",
