      "level": "N3",
      "pattern": "〜たて",
      "meaningZh": "刚……（的）",
      "formation": "Vます形去ます + たて",
      "note": "表示刚刚做好、很新鲜的状态，如「焼きたて」「できたて」「とれたて」。只能接部分动词。",
