      "level": "N3",
      "pattern": "〜だらけ",
      "meaningZh": "满是……；全是……（不好的东西）",
      "formation": "N + だらけ",
      "note": "表示某处布满了（多为不好的）东西，如「泥だらけ」「間違いだらけ」。",
