      "pattern": "〜的",
      "meaningZh": "……性的；在……方面",
      "formation": "汉语名词 + 的（作な形容詞使用）",
      "note": "接在汉语名词后构成な形容词，表示具有某种性质或从某方面来看，如「経済的」「積極的」「個人的に」。",
