      "id": "n3-grammar-102",
      "level": "N3",
      "pattern": "〜からこそ",
      "meaningZh": "正因为……才……",
      "formation": "普通形 + からこそ",
      "note": "强调原因，表示“正是因为这个理由”，多用于积极的理由。",
      "promptZh": "正因为为你着想，才说得严厉。",
      "answerJa": "あなたのことを思うからこそ、厳しく言うのです。",
      "examples": [
        {
          "ja": "あなたのことを思うからこそ、厳しく言うのです。",
          "zh": "正因为为你着想，才说得严厉。"
        },
        {
          "ja": "練習したからこそ、優勝できました。",
          "zh": "正因为练习了，才得了冠军。"
        },
        {
          "ja": "家族がいるからこそ、頑張れます。",
          "zh": "正因为有家人，才能努力下去。"
        }
      ]
